import{_ as a,o as r,c as t,a2 as s}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Character Progression","description":"","frontmatter":{},"headers":[],"relativePath":"guide/characters/progression.md","filePath":"guide/characters/progression.md"}'),o={name:"guide/characters/progression.md"};function i(n,e,l,h,d,c){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="character-progression" tabindex="-1">Character Progression <a class="header-anchor" href="#character-progression" aria-label="Permalink to &quot;Character Progression&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> These are intended changes, not confirmed live rules. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/characters/progression.html">full design specification</a>.</p><h2 id="useful-from-the-first-day" tabindex="-1">Useful from the first day <a class="header-anchor" href="#useful-from-the-first-day" aria-label="Permalink to &quot;Useful from the first day&quot;">​</a></h2><p>The intended experience is simple: an inexperienced character should already be functional. Around skill 20, you should be able to participate in a discipline. More training should expand what you can do, how consistently you do it and the challenges you can handle.</p><h2 id="three-ways-to-grow" tabindex="-1">Three ways to grow <a class="header-anchor" href="#three-ways-to-grow" aria-label="Permalink to &quot;Three ways to grow&quot;">​</a></h2><p><strong>Character skill</strong> provides capability. <strong>Knowledge</strong> opens possibilities and information. <strong>Player mastery</strong> shapes execution. Two equally trained characters may know different techniques, while two players with the same build may perform differently.</p><p>Normal skill is proposed to stop at 100; ordinary 120 progression is not planned. Reaching 100 should represent technical mastery, not finally unlocking the real game or completing every discovery.</p><h2 id="a-build-with-tradeoffs" tabindex="-1">A build with tradeoffs <a class="header-anchor" href="#a-build-with-tradeoffs" aria-label="Permalink to &quot;A build with tradeoffs&quot;">​</a></h2><p>The roughly 700-point skill budget should support primary specializations, supporting skills and smaller utility investments. Neither seven skills at 100 nor fourteen at 50 should be the automatic best answer. Deep expertise matters, but lower investment should still be useful.</p><h2 id="more-than-one-endgame" tabindex="-1">More than one endgame <a class="header-anchor" href="#more-than-one-endgame" aria-label="Permalink to &quot;More than one endgame&quot;">​</a></h2><p>You might become known as a duelist, hunter, master bowyer, chef, scholar, merchant or community organizer. These are possible aspirations, not a promise that all supporting systems exist. Knowledge, reputation, social participation and human mastery can matter without requiring every path to reach 100.</p><p><a href="/Syrolands-Public/guide/characters/skills.html">Skills and teachers</a> · <a href="/Syrolands-Public/guide/characters/techniques.html">Techniques</a> · <a href="/Syrolands-Public/guide/characters/character-creation.html">Backgrounds</a> · <a href="/Syrolands-Public/guide/characters/stats.html">Stats</a> · <a href="/Syrolands-Public/guide/professions/overview.html">Professions</a></p>',12)])])}const g=a(o,[["render",i]]);export{p as __pageData,g as default};
